/** Only original string identities can satisfy modern package relationships. */
function originalId(raw: Record<string, unknown>): string | undefined {
    return typeof raw.id === "string" && raw.id ? raw.id : undefined;
}

function assertUniqueOriginalIds(rows: Record<string, unknown>[], label: string): void {
    const ids = new Set<string>();
    for (const row of rows) {
        if (typeof row.id !== "string" && typeof row.id !== "number" && typeof row.id !== "boolean") continue;
        // Match parser identity coercion for collisions, without making repaired IDs valid references.
        const id = String(row.id);
        if (ids.has(id)) throw new PackageError(`${label} ID 重复：${id}`);
        ids.add(id);
    }
}

function originalBeatIds(episode: Record<string, unknown>): Set<string> {
    const story = episode.story;
    if (!story || typeof story !== "object" || Array.isArray(story)) return new Set();
    const beats = (story as Record<string, unknown>).beats;
    if (!Array.isArray(beats)) return new Set();
    const rows = beats.filter((beat): beat is Record<string, unknown> =>
        Boolean(beat) && typeof beat === "object" && !Array.isArray(beat));
    assertUniqueOriginalIds(rows, "场次");
    return new Set(rows.flatMap((row) => originalId(row) ?? []));
}

/** Run before parsers synthesize identities or mutate/remap the original scope. */
function validateModernShotRelations(
    episodes: Record<string, unknown>[],
    shots: Record<string, unknown>[],
): void {
    // Missing and explicitly empty episodes remain the existing legacy format.
    if (!episodes.length) return;
    assertUniqueOriginalIds(episodes, "分集");
    assertUniqueOriginalIds(shots, "分镜");
    const beatsByEpisode = new Map<string, Set<string>>();
    for (const [index, episode] of episodes.entries()) {
        assertLegacyFields(episode, ["id"], `episodes.json[${index}]`);
        const beats = originalBeatIds(episode);
        const id = originalId(episode);
        if (id) beatsByEpisode.set(id, beats);
    }
    for (const [index, shot] of shots.entries()) {
        assertLegacyFields(shot, ["id"], `shots.json[${index}]`);
        const beats = typeof shot.episodeId === "string" ? beatsByEpisode.get(shot.episodeId) : undefined;
        if (!beats) throw new PackageError(`shots.json[${index}].episodeId：分镜必须引用包内有效的原始分集 ID`);
        if (!shot.beatId) continue;
        if (typeof shot.beatId !== "string" || !beats.has(shot.beatId)) {
            throw new PackageError(`shots.json[${index}].beatId：分镜场次必须属于它引用的分集`);
        }
    }
}

function parseEpisode(
    raw: Record<string, unknown>,
    projectId: Id,
    index: number,
): Episode {
    const path = `episodes.json[${index}]`;
    assertLegacyFields(raw, ["id", "title", "createdAt", "updatedAt"], path);
    validatePackageStory(raw.story, `${path}.story`);
    const at = nowIso();
    const story = normalizeEpisodeStory(raw.story);
    // Synthesized beat identities must not merge with explicit ones during remapping.
    assertUniqueOriginalIds(story.beats.map((beat) => ({id: beat.id})), "场次");
    return {
        id: String(raw.id ?? createId("ep")),
        projectId,
        order: Number.isFinite(Number(raw.order)) ? Number(raw.order) : index,
        title: String(raw.title ?? ""),
        story,
        ...(raw.shotFilters === undefined
            ? {}
            : {shotFilters: normalizeShotFilters(raw.shotFilters)}),
        createdAt: String(raw.createdAt ?? at),
        updatedAt: String(raw.updatedAt ?? at),
        extra: pickExtra(raw, EPISODE_KEYS),
    };
}

function synthesizeFirstEpisode(
    project: Project,
    projectRaw: Record<string, unknown>,
): Episode {
    return {
        id: createId("ep"),
        projectId: project.id,
        order: 0,
        title: "",
        story: normalizeEpisodeStory(projectRaw.story),
        createdAt: project.createdAt,
        updatedAt: project.updatedAt,
    };
}

const SHOT_KEYS = [
    "propIds",
    "styleId",
    "id",
    "projectId",
    "episodeId",
    "order",
    "shotNumber",
    "status",
    "firstFrame",
    "lastFrame",
    "clip",
    "frame",
    "reference",
    "frameMediaId",
    "referenceMediaId",
    "category",
    "durationSec",
    "content",
    "notes",
    "sceneCloseup",
    "sound",
    "emotion",
    "cameraAngle",
    "cameraGear",
    "focalLength",
    "characterIds",
    "sceneId",
    "beatId",
    "extra",
];

function parseShot(
    raw: Record<string, unknown>,
    projectId: Id,
    episodeId: Id,
    index: number,
): Shot {
    const path = `shots.json[${index}]`;
    assertLegacyFields(raw, ["id", "shotNumber", "category", "content", "notes", "sceneCloseup", "sound", "emotion", "cameraAngle", "cameraGear", "focalLength", "sceneId", "beatId", "frameMediaId", "referenceMediaId"], path);
    validateLegacyIds(raw.characterIds, `${path}.characterIds`);
    for (const field of ["firstFrame", "lastFrame", "clip", "frame", "reference"]) validatePackageSlot(raw[field], `${path}.${field}`);
    const slots = parseShotPictureSlots(raw);
    return {
        id: String(raw.id ?? createId("sht")),
        projectId,
        episodeId,
        order: Number(raw.order ?? index + 1) || index + 1,
        shotNumber: String(raw.shotNumber ?? index + 1),
        status: normalizeShotStatus(raw.status),
        propIds: optionalIds(raw, "propIds"),
        styleId: raw.styleId === null ? null : optionalText(raw, "styleId"),
        firstFrame: slots.firstFrame,
        lastFrame: slots.lastFrame,
        clip: slots.clip,
        category: String(raw.category ?? ""),
        durationSec: Number(raw.durationSec ?? 0) || 0,
        content: String(raw.content ?? ""),
        notes: String(raw.notes ?? ""),
        sceneCloseup: String(raw.sceneCloseup ?? ""),
        sound: String(raw.sound ?? ""),
        emotion: String(raw.emotion ?? ""),
        cameraAngle: String(raw.cameraAngle ?? ""),
        cameraGear: String(raw.cameraGear ?? ""),
        focalLength: String(raw.focalLength ?? ""),
        characterIds: Array.isArray(raw.characterIds)
            ? raw.characterIds.map((id) => String(id))
            : [],
        sceneId: raw.sceneId ? String(raw.sceneId) : undefined,
        beatId: raw.beatId ? String(raw.beatId) : undefined,
        extra: pickExtra(raw, SHOT_KEYS),
    };
}

function remapShotStoryScope(
    shot: Shot,
    hasEpisodes: boolean,
    fallbackEpisodeId: Id,
    episodeMap: Map<string, string>,
    beatMaps: Map<string, Map<string, string>>,
): void {
    const oldEpisodeId = shot.episodeId;
    if (!hasEpisodes) {
        shot.episodeId = fallbackEpisodeId;
        const legacyBeatMap = beatMaps.values().next().value;
        shot.beatId = shot.beatId ? legacyBeatMap?.get(shot.beatId) : undefined;
        return;
    }
    const episodeId = episodeMap.get(oldEpisodeId);
    if (!episodeId) throw new PackageError("分镜分集 ID 无法重映射");
    shot.episodeId = episodeId;
    if (!shot.beatId) return;
    const beatId = beatMaps.get(oldEpisodeId)?.get(shot.beatId);
    if (!beatId) throw new PackageError("分镜场次 ID 无法重映射");
    shot.beatId = beatId;
}

export function remapId(
    map: Map<string, string>,
    oldId: string | undefined,
    prefix: string,
) {
    if (!oldId) return undefined;
    const existing = map.get(oldId);
    if (existing) return existing;
    const next = createId(prefix);
    map.set(oldId, next);
    return next;
}

type MemoryPackage = {
    memories: ProjectMemory[];
    memoryVersions: ProjectMemoryVersion[];
};

/** Validate the whole aggregate before any imported project or media is persisted. */
function parseMemoryPackage(
    rawRows: unknown,
    rawVersions: unknown,
    projectId: unknown,
): MemoryPackage {
    const rows = z
        .array(projectMemorySchema)
        .safeParse(rawRows === undefined ? [] : rawRows);
    const versions = z
        .array(projectMemoryVersionSchema)
        .safeParse(rawVersions === undefined ? [] : rawVersions);
    if (!rows.success || !versions.success)
        throw new PackageError("项目记忆或历史版本格式无效");
    const memories = rows.data;
    const memoryVersions = versions.data;
    const fail = () => {
        throw new PackageError("项目记忆的归属、替代关系或版本链无效");
    };
    const byId = new Map(memories.map((row) => [row.id, row]));
    if (
        byId.size !== memories.length ||
        new Set(memoryVersions.map((row) => row.versionId)).size !==
        memoryVersions.length
    )
        fail();
    const chains = new Map<string, ProjectMemoryVersion[]>();
    for (const version of memoryVersions) {
        if (
            !byId.has(version.memoryId) ||
            version.projectId !== projectId ||
            version.snapshot.id !== version.memoryId ||
            version.snapshot.projectId !== projectId ||
            version.snapshot.revision !== version.revision
        )
            fail();
        const chain = chains.get(version.memoryId) ?? [];
        chain.push(version);
        chains.set(version.memoryId, chain);
    }
    const validateSnapshot = (row: ProjectMemory) => {
        if (row.projectId !== projectId || row.projectId === "studio") fail();
        if (row.source.kind === "summary" && row.source.projectId !== projectId)
            fail();
        if (row.supersededBy === row.id) fail();
    };
    for (const row of memories) {
        validateSnapshot(row);
        const chain = (chains.get(row.id) ?? []).sort(
            (a, b) => a.revision - b.revision,
        );
        if (
            chain.length !== row.revision ||
            chain.some((v, index) => v.revision !== index + 1)
        )
            fail();
        if (JSON.stringify(chain.at(-1)?.snapshot) !== JSON.stringify(row)) fail();
        for (const version of chain) validateSnapshot(version.snapshot);
        const visited = new Set<string>([row.id]);
        let next = row.supersededBy;
        while (next) {
            if (visited.has(next)) fail();
            visited.add(next);
            next = byId.get(next)?.supersededBy;
        }
    }
    // Match CRUD topic identity after validating the original chain, so normalization
    // cannot conceal inconsistent source snapshots or bypass same-topic conflicts.
    for (const row of memories) row.topicKey = normalizeMemoryText(row.topicKey);
    for (const version of memoryVersions) {
        version.snapshot.topicKey = normalizeMemoryText(version.snapshot.topicKey);
    }
    return {memories, memoryVersions};
}

function detachedMemorySource(row: ProjectMemory): MemorySource {
    const source = row.source;
    if (source.kind === "imported") return {...source};
    return {
        kind: "imported",
        originProjectId: row.projectId,
        originMemoryId: row.id,
        originalKind: source.kind,
        excerpt:
            source.kind === "summary" ? source.excerpt : row.body.slice(0, 3000),
        ...(source.kind === "summary"
            ? {
                taskTitle: source.taskTitle,
                summaryId: source.summaryId,
                summaryRevision: source.summaryRevision,
                evidence: source.evidence,
            }
            : {}),
    };
}

function remapMemoryPackage(
    input: MemoryPackage,
    projectId: Id,
    at: string,
): MemoryPackage {
    const ids = new Map(input.memories.map((row) => [row.id, createId("pm")]));
    const snapshot = (row: ProjectMemory): ProjectMemory => ({
        ...row,
        id: ids.get(row.id)!,
        projectId,
        source: detachedMemorySource(row),
        supersededBy: row.supersededBy ? ids.get(row.supersededBy) : undefined,
    });
    const memoryVersions = input.memoryVersions.map((version) => ({
        ...version,
        versionId: createId("pmv"),
        memoryId: ids.get(version.memoryId)!,
        projectId,
        snapshot: snapshot(version.snapshot),
    }));
    const memories = input.memories.map((row) => {
        const current = {
            ...snapshot(row),
            status: "pending_review" as const,
            revision: row.revision + 1,
            updatedAt: at,
        };
        delete current.reviewedAt;
        const detachedReplacement = input.memoryVersions.some(
            (version) =>
                version.memoryId === row.id &&
                version.snapshot.supersededBy &&
                !ids.has(version.snapshot.supersededBy),
        );
        memoryVersions.push({
            versionId: createId("pmv"),
            memoryId: current.id,
            projectId,
            revision: current.revision,
            reason: `导入项目备份，等待重新审核${detachedReplacement ? "；原替代条目已删除，已解除关联" : ""}`,
            snapshot: current,
        });
        return current;
    });
    return {memories, memoryVersions};
}

export interface ProjectPackageJson {
    project: unknown;
    characters?: unknown;
    scenes?: unknown;
    props?: unknown;
    styles?: unknown;
    episodes?: unknown;
    shots?: unknown;
    memories?: unknown;
    memoryVersions?: unknown;
    references?: unknown;
    referenceChunks?: unknown;
    audioPackage?: unknown;
}

export function parseProjectPackageRows(raw: ProjectPackageJson) {
    const projectRaw = asRecord(
        raw.project,
        "project.json",
    );
    const charactersRaw = asArray(
        raw.characters,
        "characters.json",
    );
    const scenesRaw = asArray(raw.scenes, "scenes.json");
    const propsRaw = asArray(raw.props, "props.json");
    const stylesRaw = asArray(raw.styles, "styles.json");
    const episodesFile = raw.episodes;
    const episodesRaw =
        episodesFile == null ? [] : asArray(episodesFile, "episodes.json");
    const shotsRaw = asArray(raw.shots, "shots.json");
    const memoryPackage = parseMemoryPackage(
        raw.memories,
        raw.memoryVersions,
        projectRaw.id,
    );
    const referencePackage = parseReferencePackage(raw.references, raw.referenceChunks, projectRaw.id);
    const hasEpisodes = episodesRaw.length > 0;
    validateModernShotRelations(episodesRaw, shotsRaw);

    const project = parseProject(projectRaw, "导入的项目");
    const audioPackage = parseAudioPackage(raw.audioPackage, projectRaw.id, getProjectKind(project));
    if (project.musicVariantLinks !== undefined) {
        if (getProjectKind(project) !== "music" || !audioPackage) throw new PackageError("音乐草稿关联缺少所属音乐项目");
        const drafts = new Map(audioPackage.musicDrafts.map(row => [row.id, row]));
        if (drafts.size !== audioPackage.musicDrafts.length) throw new PackageError("音乐草稿 ID 重复");
        for (const [sourceId, group] of Object.entries(project.musicVariantLinks)) {
            const entries = Object.entries(group);
            if (!drafts.has(sourceId) || !entries.some(([, id]) => id === sourceId) || new Set(entries.map(([, id]) => id)).size !== entries.length) throw new PackageError("音乐草稿关联缺少真实归属");
            for (const [variant, id] of entries) {
                const draft = drafts.get(id);
                const actual = draft?.settings.engine === "flowmusic" ? "flowmusic" : draft?.settings.custom ? "suno-custom" : "suno-simple";
                if (!draft || actual !== variant) throw new PackageError("音乐草稿关联的类型或记录无效");
                const other = project.musicVariantLinks[id];
                if (!other || ["suno-simple", "suno-custom", "flowmusic"].some(key => other[key as keyof typeof other] !== group[key as keyof typeof group])) throw new PackageError("音乐草稿关联不一致");
            }
        }
    }
    if (getProjectKind(project) !== "video" && (episodesRaw.length || shotsRaw.length || charactersRaw.length || scenesRaw.length || propsRaw.length || stylesRaw.length)) throw new PackageError("音频或音乐项目不能包含视频记录");
    return {
        projectRaw, charactersRaw, scenesRaw, propsRaw, stylesRaw, episodesRaw, shotsRaw,
        memoryPackage, referencePackage, hasEpisodes, project, audioPackage
    };
}

export function remapProjectPackageRows(parsed: ReturnType<typeof parseProjectPackageRows>, {projectId, at, mediaMap}: {
    projectId: string; at: string; mediaMap: Map<string, string>;
}) {
    const {
        projectRaw,
        charactersRaw,
        scenesRaw,
        propsRaw,
        stylesRaw,
        episodesRaw,
        shotsRaw,
        memoryPackage,
        hasEpisodes,
        audioPackage
    } = parsed;
    const project = structuredClone(parsed.project);
    project.id = projectId;
    project.createdAt = at;
    project.updatedAt = at;
    const {memories, memoryVersions} = remapMemoryPackage(
        memoryPackage,
        projectId,
        at,
    );
    if (!hasEpisodes) {
        project.columnSettings = {visible: [...DEFAULT_VISIBLE_COLUMNS]};
    }

    const characterMap = new Map<string, string>();
    const sceneMap = new Map<string, string>();
    const propMap = new Map<string, string>();
    const styleMap = new Map<string, string>();
    const episodeMap = new Map<string, string>();
    const beatMaps = new Map<string, Map<string, string>>();
    const shotMap = new Map<string, string>();

    const remappedAudioPackage = remapAudioPackage(audioPackage, projectId, mediaMap);
    if (project.musicVariantLinks && audioPackage && remappedAudioPackage) {
        // The codec preserves array order while remapping immutable row IDs.
        const drafts = new Map(audioPackage.musicDrafts.map((row, index) => [row.id, remappedAudioPackage.musicDrafts[index]?.id]));
        const target = (id: string): string => {
            const next = drafts.get(id);
            if (!next) throw new PackageError("音乐草稿关联的记录缺失");
            return next;
        };
        project.musicVariantLinks = Object.fromEntries(Object.entries(project.musicVariantLinks).map(([id, group]) => [target(id), Object.fromEntries(Object.entries(group).map(([variant, member]) => [variant, target(member)]))]));
    }
    const mapMedia = (id?: string) => (id ? mediaMap.get(id) : undefined);

    if (project.coverMediaId) {
        const mappedCover = mapMedia(project.coverMediaId);
        if (mappedCover) project.coverMediaId = mappedCover;
        else delete project.coverMediaId;
    }

    const characters = charactersRaw.map((raw, index) => {
        const character = parseCharacter(raw, projectId, `characters.json[${index}]`);
        const newId = remapId(characterMap, character.id, "chr")!;
        character.id = newId;
        character.projectId = projectId;
        const images: Character["slots"] = {};
        for (const [slot, value] of Object.entries(character.slots)) {
            if (!value) continue;
            images[slot as keyof Character["slots"]] = remapSlot(value, mapMedia);
        }
        character.slots = images;
        return character;
    });

    const scenes = scenesRaw.map((raw, index) => {
        const scene = parseScene(raw, projectId, `scenes.json[${index}]`);
        scene.id = remapId(sceneMap, scene.id, "scn")!;
        scene.projectId = projectId;
        const images: Scene["slots"] = {};
        for (const [slot, value] of Object.entries(scene.slots)) {
            if (!value) continue;
            images[slot as keyof Scene["slots"]] = remapSlot(value, mapMedia);
        }
        scene.slots = images;
        return scene;
    });

    const props = propsRaw.map((raw, index) => {
        const prop = parseProp(raw, projectId, `props.json[${index}]`);
        prop.id = remapId(propMap, prop.id, "prp")!;
        prop.slots = Object.fromEntries(
            Object.entries(prop.slots).map(([slot, value]) => [
                slot,
                value ? remapSlot(value, mapMedia) : value,
            ]),
        );
        return prop;
    });

    const styles = stylesRaw.map((raw, index) => {
        const style = parseStyle(raw, projectId, `styles.json[${index}]`);
        style.id = remapId(styleMap, style.id, "sty")!;
        style.slots = Object.fromEntries(
            Object.entries(style.slots).map(([slot, value]) => [
                slot,
                value ? remapSlot(value, mapMedia) : value,
            ]),
        );
        return style;
    });

    if (project.defaultStyleId !== undefined)
        project.defaultStyleId = styleMap.get(project.defaultStyleId);

    let parsedEpisodes: Episode[] = [];
    if (getProjectKind(project) === "video") {
        parsedEpisodes = hasEpisodes
            ? episodesRaw.map((raw, index) => parseEpisode(raw, projectId, index))
            : [synthesizeFirstEpisode(project, projectRaw)];
    }

    const episodes = parsedEpisodes.map((episode) => {
        const filters = getEpisodeShotFilters(episode, project);
        const oldEpisodeId = episode.id;
        const newId = remapId(episodeMap, oldEpisodeId, "ep")!;
        const beatMap = new Map<string, string>();
        beatMaps.set(oldEpisodeId, beatMap);
        episode.id = newId;
        episode.projectId = projectId;
        episode.story = {
            ...episode.story,
            beats: episode.story.beats.map((beat) => {
                const newBeatId = remapId(beatMap, beat.id, "beat")!;
                return {
                    ...beat,
                    id: newBeatId,
                    characterIds: beat.characterIds
                        .map((id) => characterMap.get(id))
                        .filter((id): id is string => Boolean(id)),
                    sceneId: beat.sceneId ? sceneMap.get(beat.sceneId) : undefined,
                };
            }),
        };
        episode.shotFilters = {
            ...filters,
            beatIds: filters.beatIds.flatMap((id) => {
                if (id === SHOT_UNASSIGNED_BEAT) return [id];
                const mapped = beatMap.get(id);
                return mapped ? [mapped] : [];
            }),
        };
        return episode;
    });
    // Legacy filters have been migrated per episode; never retain obsolete beat IDs.
    project.shotSettings.filters = normalizeShotFilters(undefined);

    const fallbackEpisodeId = episodes[0]?.id ?? createId("ep");

    const shots = shotsRaw.map((raw, index) => {
        // Modern owners were checked before any repair; legacy scopes are deliberately ignored.
        const oldEpisodeId = hasEpisodes && typeof raw.episodeId === "string" ? raw.episodeId : fallbackEpisodeId;
        const shot = parseShot(raw, projectId, oldEpisodeId, index);
        remapShotStoryScope(shot, hasEpisodes, fallbackEpisodeId, episodeMap, beatMaps);
        shot.id = remapId(shotMap, shot.id, "sht")!;
        shot.projectId = projectId;
        shot.firstFrame = remapSlot(shot.firstFrame, mapMedia);
        shot.lastFrame = remapSlot(shot.lastFrame, mapMedia);
        shot.clip = remapSlot(shot.clip, mapMedia);
        shot.characterIds = shot.characterIds
            .map((id) => characterMap.get(id))
            .filter((id): id is string => Boolean(id));
        shot.sceneId = shot.sceneId ? sceneMap.get(shot.sceneId) : undefined;
        if (shot.propIds !== undefined)
            shot.propIds = shot.propIds.flatMap((id) => propMap.get(id) ?? []);
        // A missing explicit style must not unexpectedly inherit a different default.
        if (typeof shot.styleId === "string")
            shot.styleId = styleMap.get(shot.styleId) ?? null;
        return shot;
    });

    return {
        project,
        characters,
        scenes,
        props,
        styles,
        episodes,
        shots,
        memories,
        memoryVersions,
        remappedAudioPackage
    };
}

import {binaryByteLength} from "@/domain/binary";
import {readBinaryBlob, verifyBinaryAvailable} from "@/lib/storage/binary";
import {BinaryUnavailableError} from "@/lib/storage/nativeBinary";
import {verifiedShotMediaIndex, type ShotBinaryState} from "@/lib/shotMedia";
import JSZip from "jszip";
import {db} from "@/db/database";
import {SHOT_COLUMNS} from "@/domain/columns";
import {parseShotPictureSlots} from "@/domain/slot";
import type {GenerationResult, Id, MediaRecord, ShotPictureField} from "@/domain/types";
import {episodeLabel, normalizeEpisodeStory, normalizeProjectMode} from "@/domain/types";
import {flushPendingDrafts} from "@/lib/debouncedDraft";
import {deriveEpisodeDelivery, episodeDeliveryCsv} from "@/lib/episodeDelivery";

export const HANDOFF_FORMAT = "cuepoint-handoff-v1" as const;

type SlotState = "empty" | "exported" | "placeholder" | "missing" | "foreign" | "wrong-kind" | "empty-file" | "corrupt";

interface HandoffSlot {
    prompt: string;
    state: SlotState;
    required: boolean;
    expectedResult?: GenerationResult;
    path?: string;
    originalFilename?: string;
    mimeType?: string;
    byteSize?: number;
}

const SLOT_LABELS: Record<ShotPictureField, string> = {firstFrame: "首帧", lastFrame: "尾帧", clip: "成片"};

/** One path component only; user-authored IDs and names never become directories. */
function safeComponent(value: string, fallback: string): string {
    const safe = Array.from(value.normalize("NFKC"), character => character.charCodeAt(0) < 32 ? "-" : character).join("")
        .replace(/[\u007f\\/:*?"<>|]/g, "-")
        .replace(/\s+/g, " ").replace(/^\.+|[. ]+$/g, "").trim();
    let bounded = "";
    for (const character of safe) {
        if (new TextEncoder().encode(bounded + character).length > 100) break;
        bounded += character;
    }
    return !bounded || /^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(bounded)
        ? fallback : bounded;
}

function inspectSlot(
    field: ShotPictureField,
    prompt: string,
    result: GenerationResult | undefined,
    media: MediaRecord | undefined,
    projectId: Id,
    folder: string,
    availability?: ShotBinaryState,
): HandoffSlot {
    const slot: HandoffSlot = {
        prompt, state: "empty", required: field !== "lastFrame",
        ...(result ? {expectedResult: {mediaId: result.mediaId, kind: result.kind}} : {}),
    };
    if (!result) return slot;
    if (!media) return {...slot, state: "missing"};
    if (media.projectId !== projectId) return {...slot, state: "foreign"};
    if ((result.kind !== "image" && result.kind !== "video") ||
        (field !== "clip" && result.kind !== "image") || !media.mimeType.startsWith(`${result.kind}/`)) {
        return {...slot, state: "wrong-kind"};
    }
    if (binaryByteLength(media.blob) === 0) return {...slot, state: "empty-file"};
    if (availability === "missing" || availability === "corrupt") return {...slot, state: availability};
    return {
        ...slot,
        state: field === "clip" && result.kind === "image" ? "placeholder" : "exported",
        path: `${folder}/${field}-${safeMediaFilename(media.filename, result.kind === "image" ? "image" : "video")}`,
        originalFilename: media.filename, mimeType: media.mimeType, byteSize: binaryByteLength(media.blob),
    };
}

function safeMediaFilename(filename: string, fallback: string): string {
    const extension = filename.match(/\.([a-zA-Z0-9]{1,10})$/)?.[0] ?? "";
    return `${safeComponent(extension ? filename.slice(0, -extension.length) : filename, fallback)}${extension}`;
}

function slotWarning(field: ShotPictureField, slot: HandoffSlot): string | undefined {
    const label = SLOT_LABELS[field];
    switch (slot.state) {
        case "empty":
            return slot.required ? `${label}尚未选择素材` : undefined;
        case "placeholder":
            return "成片为图片占位，仍缺少完成的视频";
        case "missing":
            return `${label}引用的素材不存在`;
        case "corrupt":
            return `${label}素材内容已损坏，未导出`;
        case "foreign":
            return `${label}引用了其他项目的素材，未导出`;
        case "wrong-kind":
            return `${label}素材类型不匹配，未导出`;
        case "empty-file":
            return `${label}素材文件为空，未导出`;
        case "exported":
            return undefined;
    }
}

/** Export only current-episode selected results; this is not a restorable project backup. */
export async function exportProductionHandoff(
    projectId: Id,
    episodeId: Id,
    onProgress?: (percent: number) => void,
): Promise<{ blob: Blob; filename: string; shotCount: number; missingCount: number }> {
    onProgress?.(0);
    await flushPendingDrafts(projectId);
    const snapshot = await db.transaction("r",
        [db.projects, db.episodes, db.shots, db.characters, db.scenes, db.props, db.styles, db.media], async (db) => {
            const project = await db.projects.get(projectId);
            const episode = await db.episodes.get(episodeId);
            if (!project || !episode || episode.projectId !== projectId) throw new Error("找不到当前项目或分集");
            const shots = (await db.shots.where("episodeId").equals(episodeId).toArray())
                .filter((shot) => shot.projectId === projectId)
                .sort((a, b) => a.order - b.order || a.id.localeCompare(b.id))
                .map((shot) => ({...shot, ...parseShotPictureSlots(shot as unknown as Record<string, unknown>)}));
            if (!shots.length) throw new Error("当前分集还没有镜头，无法导出素材交付包");
            const mediaIds = new Set(shots.flatMap((shot) => [shot.firstFrame.result?.mediaId, shot.lastFrame.result?.mediaId, shot.clip.result?.mediaId])
                .filter((id): id is string => Boolean(id)));
            const characterIds = [...new Set(shots.flatMap((shot) => shot.characterIds))];
            const sceneIds = [...new Set(shots.flatMap((shot) => shot.sceneId ? [shot.sceneId] : []))];
            const propIds = [...new Set(shots.flatMap((shot) => shot.propIds ?? []))];
            const styleIds = [...new Set(shots.flatMap((shot) => {
                const id = shot.styleId === undefined ? project.defaultStyleId : shot.styleId;
                return id ? [id] : [];
            }))];
            const [characters, scenes, props, styles, media] = await Promise.all([
                db.characters.bulkGet(characterIds), db.scenes.bulkGet(sceneIds), db.props.bulkGet(propIds),
                db.styles.bulkGet(styleIds), db.media.bulkGet([...mediaIds]),
            ]);
            const owned = <T extends { projectId: Id }>(item: T | undefined): item is T =>
                item !== undefined && item.projectId === projectId;
            return {
                project, episode, shots,
                characters: characters.filter(owned),
                scenes: scenes.filter(owned),
                props: props.filter(owned),
                styles: styles.filter(owned),
                media: new Map(media.filter((item) => item !== undefined).map((item) => [item.id, item])),
            };
        });
    onProgress?.(10);
    const {project, episode} = snapshot;
    const files = new Map<string, Blob>();
    const states = new Map<string, ShotBinaryState>();
    for (const record of snapshot.media.values()) {
        if (record.projectId !== projectId || binaryByteLength(record.blob) === 0) continue;
        try {
            files.set(record.id, await readBinaryBlob(record.blob));
            states.set(record.id, "ready");
        } catch (error) {
            if (!(error instanceof BinaryUnavailableError)) throw error;
            states.set(record.id, error.availability);
        }
    }
    // All authored camera/sound fields belong in the handoff, even when hidden in the editor.
    const delivery = deriveEpisodeDelivery({
        ...snapshot, media: verifiedShotMediaIndex(snapshot.media, states), project: {
            ...project, columnSettings: {visible: SHOT_COLUMNS.map((column) => column.id)},
        }
    });
    const zip = new JSZip();
    const beats = normalizeEpisodeStory(episode.story).beats;
    const slots = ["firstFrame", "lastFrame", "clip"] as const;
    const rows = delivery.rows.map((row, index) => {
        const shot = row.shot;
        // Sequence guarantees uniqueness even for duplicate/hostile labels and truncated IDs.
        const folder = `shots/${String(index + 1).padStart(4, "0")}-${safeComponent(shot.shotNumber, "shot")}-${safeComponent(shot.id, "id")}`;
        const media = Object.fromEntries(slots.map((field) => {
            const result = shot[field].result;
            const record = result ? snapshot.media.get(result.mediaId) : undefined;
            const slot = inspectSlot(field, shot[field].prompt, result, record, projectId, folder, record ? states.get(record.id) : undefined);
            if (slot.path && record) zip.file(slot.path, files.get(record.id)!);
            return [field, slot];
        })) as Record<ShotPictureField, HandoffSlot>;
        const warnings: string[] = [];
        if (row.missing.includes("content")) warnings.push("镜头内容未填写");
        if (row.missing.includes("duration")) warnings.push("镜头时长未填写");
        if (row.missing.includes("scene")) warnings.push("场景未关联或已不存在");
        const linked = (ids: Id[], records: Array<{ id: Id; name: string }>, label: string) => ids.map((id) => {
            const record = records.find((item) => item.id === id);
            if (!record) warnings.push(`${label}关联失效：${id}`);
            return {id, name: record?.name ?? null};
        });
        const characters = linked(shot.characterIds, snapshot.characters, "角色");
        const props = linked(shot.propIds ?? [], snapshot.props, "道具");
        const effectiveStyleId = shot.styleId === undefined ? project.defaultStyleId : shot.styleId;
        const style = effectiveStyleId ? linked([effectiveStyleId], snapshot.styles, "风格")[0] : null;
        const beat = beats.find((item) => item.id === shot.beatId);
        if (shot.beatId && !beat) warnings.push(`场次关联失效：${shot.beatId}`);
        for (const field of slots) {
            const warning = slotWarning(field, media[field]);
            if (warning) warnings.push(warning);
        }
        const metadata = {
            projectId,
            episodeId,
            shotId: shot.id,
            order: row.order,
            shotNumber: shot.shotNumber,
            status: row.status,
            statusLabel: row.statusLabel,
            durationSec: shot.durationSec,
            content: shot.content,
            notes: shot.notes,
            category: shot.category,
            sceneCloseup: shot.sceneCloseup,
            sound: shot.sound,
            emotion: shot.emotion,
            cameraAngle: shot.cameraAngle,
            cameraGear: shot.cameraGear,
            focalLength: shot.focalLength,
            beat: shot.beatId ? {id: shot.beatId, title: beat?.title ?? null} : null,
            characters,
            scene: shot.sceneId ? {
                id: shot.sceneId,
                name: snapshot.scenes.find((item) => item.id === shot.sceneId)?.name ?? null
            } : null,
            props,
            style,
            styleSource: row.styleSource,
            media,
            warnings,
            folder,
        };
        const detail = [
            `镜头 ${row.order} · ${shot.shotNumber}`, `镜头 ID：${shot.id}`, `状态（人工标记）：${row.statusLabel}`,
            `时长：${shot.durationSec} 秒`, `场次：${row.beat}`, `角色：${row.characters || "无"}`,
            `场景：${row.scene || "未关联"}`, `道具：${row.props || "无"}`, `风格：${row.style}（${row.styleSource}）`,
            `内容：\n${shot.content}`, `备注：\n${shot.notes}`,
            ...delivery.columns.map((column) => `${column.label}：\n${row.values[column.id] ?? ""}`),
            "素材：", ...slots.map((field) => `${SLOT_LABELS[field]}：${media[field].path ?? slotWarning(field, media[field]) ?? "未选择（可选）"}\n素材描述：\n${media[field].prompt}`),
            "检查项：", ...(warnings.length ? warnings : ["无缺失项"]),
        ].join("\n\n");
        zip.file(`${folder}/shot.txt`, detail);
        return metadata;
    });
    const missingCount = rows.filter((row) => row.warnings.length > 0).length;
    const title = normalizeProjectMode(project.mode) === "film" ? project.name : `${project.name} · ${episodeLabel(episode)}`;
    zip.file("manifest.json", JSON.stringify({
        format: HANDOFF_FORMAT, exportedAt: new Date().toISOString(),
        project: {
            id: projectId,
            name: project.name,
            mode: normalizeProjectMode(project.mode),
            aspectPreset: project.aspectPreset
        },
        episode: {id: episodeId, order: episode.order, title: episode.title},
        shotCount: rows.length, missingCount, totalDurationSec: delivery.totalDurationSec, shots: rows,
    }, null, 2));
    zip.file("shots.csv", episodeDeliveryCsv(delivery));
    zip.file("missing.md", [`# 缺失与待确认清单`, `${missingCount} / ${rows.length} 个镜头有待确认项。尾帧未选择不计为缺失。`,
        ...rows.filter((row) => row.warnings.length > 0).map((row) => `## ${row.order} · ${row.shotNumber}\n\n镜头 ID：${row.shotId}\n\n${row.warnings.map((warning) => `- ${warning}`).join("\n")}`),
        ...(missingCount ? [] : ["所有镜头已具备内容、时长、有效场景、首帧和成片视频。"]),
    ].join("\n\n"));
    zip.file("README.md", [
        `# ${title} — 素材交付包`,
        `共 ${rows.length} 个镜头，合计 ${delivery.totalDurationSec} 秒；${missingCount} 个镜头有待确认项。`,
        "这是供制作与剪辑使用的素材交付包，不是可还原的项目备份。仅包含当前分集的镜头信息及已选择的首帧、尾帧、成片原始文件。",
        "请先查看 missing.md，再按 shots.csv 顺序使用 shots/ 下的素材。每个镜头文件夹中的 shot.txt 保留完整文字；manifest.json 提供稳定 ID、关联信息、素材路径与原始文件名。",
        "文件夹以镜头顺序编号，随后是镜号和镜头 ID。素材文件名以 firstFrame、lastFrame、clip 标明用途。路径中的特殊字符已处理，原始文件字节未转码。",
        "尾帧为可选项。成片槽中的图片按占位图导出，仍会提示缺少完成的视频。人工标记的状态不代表所有素材已经齐全。",
    ].join("\n\n"));
    onProgress?.(20);
    // Media are usually compressed already; STORE preserves bytes with lower CPU/memory overhead.
    const blob = await zip.generateAsync({
        type: "blob",
        compression: "STORE"
    }, (event) => onProgress?.(20 + event.percent * 0.8));
    for (const id of files.keys()) await verifyBinaryAvailable(snapshot.media.get(id)!.blob);
    return {blob, filename: `${safeComponent(title, "素材交付")}-素材交付.zip`, shotCount: rows.length, missingCount};
}

