const manifestSchema = z.object({
    format: z.literal(PACKAGE_FORMAT),
    exportedAt: z.string().optional(),
});

function extFor(mimeType: string, filename: string): string {
    const fromName = filename.split(".").pop();
    if (fromName && fromName !== filename && fromName.length <= 5)
        return fromName;
    if (mimeType.includes("png")) return "png";
    if (mimeType.includes("webp")) return "webp";
    if (mimeType.includes("gif")) return "gif";
    if (mimeType.includes("mp4")) return "mp4";
    if (mimeType.includes("webm")) return "webm";
    if (mimeType.includes("quicktime")) return "mov";
    if (mimeType.startsWith("audio/")) {
        if (mimeType.includes("wav")) return "wav";
        if (mimeType.includes("mpeg")) return "mp3";
        if (mimeType.includes("ogg")) return "ogg";
        if (mimeType.includes("flac")) return "flac";
        if (mimeType.includes("aac")) return "aac";
        return "audio";
    }
    if (mimeType.startsWith("video/")) return "mp4";
    return "jpg";
}

function mimeForFilename(filename: string): string {
    const extension = filename.split(".").pop()?.toLowerCase();
    const known: Record<string, string> = {
        wav: "audio/wav",
        mp3: "audio/mpeg",
        ogg: "audio/ogg",
        opus: "audio/ogg",
        flac: "audio/flac",
        aac: "audio/aac",
        m4a: "audio/mp4",
        png: "image/png",
        jpg: "image/jpeg",
        jpeg: "image/jpeg",
        jfif: "image/jpeg",
        webp: "image/webp",
        gif: "image/gif",
        mp4: "video/mp4",
        webm: "video/webm",
        mov: "video/quicktime",
    };
    return (extension && known[extension]) || "application/octet-stream";
}

export async function exportProjectZip(projectId: Id): Promise<Blob> {
    // Snapshot all JSON rows and referenced Blobs under one read transaction.
    // Compression happens after the transaction closes; no external awaits hold it open.
    const {
        audioPackage,
        project,
        characters,
        scenes,
        props,
        styles,
        episodes,
        shots,
        mediaRecords,
        memories,
        memoryVersions,
        references,
        referenceChunks,
    } = await db.transaction(
        "r",
        [
            ...AUDIO_TABLES,
            db.projects,
            db.characters,
            db.scenes,
            db.props,
            db.styles,
            db.episodes,
            db.shots,
            db.media,
            db.materialUses,
            db.projectMemories,
            db.projectMemoryVersions,
            db.projectReferences,
            db.referenceChunks,
        ],
        async (db) => {
            const project = await db.projects.get(projectId);
            if (!project) throw new PackageError("项目不存在");
            const [
                characters,
                scenes,
                props,
                styles,
                episodes,
                shots,
                memories,
                memoryVersions,
                references,
                referenceChunks,
            ] = await Promise.all([
                db.characters.where("projectId").equals(projectId).toArray(),
                db.scenes.where("projectId").equals(projectId).toArray(),
                db.props.where("projectId").equals(projectId).toArray(),
                db.styles.where("projectId").equals(projectId).toArray(),
                db.episodes.where("projectId").equals(projectId).sortBy("order"),
                db.shots.where("projectId").equals(projectId).sortBy("order"),
                db.projectMemories.where("projectId").equals(projectId).toArray(),
                db.projectMemoryVersions.where("projectId").equals(projectId).toArray(),
                db.projectReferences.where("projectId").equals(projectId).toArray(),
                db.referenceChunks.where("projectId").equals(projectId).toArray(),
            ]);
            const mediaIds = await collectMediaIds(projectId, db);
            const mediaRecords = (await db.media.bulkGet([...mediaIds])).filter(
                (media): media is MediaRecord =>
                    media !== undefined && media.projectId === projectId,
            );
            if (getProjectKind(project) !== "video" && mediaRecords.length !== mediaIds.size) throw new PackageError("音频项目存在缺失或归属错误的文件，请恢复文件后再备份");
            return {
                audioPackage: await snapshotAudioPackage(projectId, db),
                project,
                characters,
                scenes,
                props,
                styles,
                episodes,
                shots,
                mediaRecords,
                memories,
                memoryVersions,
                references,
                referenceChunks,
            };
        },
    );
    const zip = new JSZip();
    zip.file(
        "manifest.json",
        JSON.stringify(
            {
                format: PACKAGE_FORMAT,
                exportedAt: nowIso(),
                projectName: project.name,
            },
            null,
            2,
        ),
    );
    if (getProjectKind(project) !== "video") zip.file("audioProject.json", JSON.stringify(audioPackage));
    zip.file("project.json", JSON.stringify(project, null, 2));
    zip.file("characters.json", JSON.stringify(characters, null, 2));
    zip.file("scenes.json", JSON.stringify(scenes, null, 2));
    zip.file("props.json", JSON.stringify(props, null, 2));
    zip.file("styles.json", JSON.stringify(styles, null, 2));
    zip.file("episodes.json", JSON.stringify(episodes, null, 2));
    zip.file("shots.json", JSON.stringify(shots, null, 2));
    zip.file("memories.json", JSON.stringify(memories, null, 2));
    zip.file("memoryVersions.json", JSON.stringify(memoryVersions, null, 2));
    zip.file("references.json", JSON.stringify(references));
    zip.file("referenceChunks.json", JSON.stringify(referenceChunks));
    zip.file("mediaMetadata.json", JSON.stringify(mediaRecords.map((media) => ({
        id: media.id,
        projectId: media.projectId,
        filename: media.filename,
        mimeType: media.mimeType,
        libraryRetained: media.libraryRetained,
    }))));
    for (const media of mediaRecords) {
        const filename = `media/${media.id}.${extFor(media.mimeType, media.filename)}`;
        zip.file(filename, await readBinaryBlob(media.blob));
    }
    const blob = await zip.generateAsync({type: "blob"});
    for (const media of mediaRecords) await verifyBinaryAvailable(media.blob);
    return blob;
}

export async function importProjectZip(file: Blob): Promise<Project> {
    const zip = await JSZip.loadAsync(file).catch(() => {
        throw new PackageError("无法读取 zip 文件");
    });
    const manifestFile = zip.file("manifest.json");
    if (!manifestFile) throw new PackageError("缺少 manifest.json");
    const manifestJson = JSON.parse(
        await manifestFile.async("string"),
    ) as unknown;
    const manifest = manifestSchema.safeParse(manifestJson);
    if (!manifest.success) {
        throw new PackageError("不是小光点项目包（manifest.format 不匹配）");
    }

    const readJson = async (name: string, required = false) => {
        const entry = zip.file(name);
        if (!entry) {
            if (required) throw new PackageError(`缺少 ${name}`);
            return undefined;
        }
        try {
            return JSON.parse(await entry.async("string")) as unknown;
        } catch {
            throw new PackageError(`${name} 不是合法 JSON`);
        }
    };

    const parsed = parseProjectPackageRows({
        project: await readJson("project.json", true),
        characters: await readJson("characters.json"),
        scenes: await readJson("scenes.json"),
        props: await readJson("props.json"),
        styles: await readJson("styles.json"),
        episodes: await readJson("episodes.json"),
        shots: await readJson("shots.json"),
        memories: await readJson("memories.json"),
        memoryVersions: await readJson("memoryVersions.json"),
        references: await readJson("references.json"),
        referenceChunks: await readJson("referenceChunks.json"),
        audioPackage: await readJson("audioProject.json"),
    });
    const {projectRaw, referencePackage} = parsed;
    const mediaMetadataRaw = await readJson("mediaMetadata.json");
    const mediaMetadata = new Map<string, { filename: string; mimeType: string; libraryRetained?: boolean }>();
    if (mediaMetadataRaw !== undefined) {
        for (const raw of asArray(mediaMetadataRaw, "mediaMetadata.json")) {
            const row = asRecord(raw, "mediaMetadata.json");
            if (typeof row.id !== "string" || !row.id || /[/\\]/.test(row.id) || mediaMetadata.has(row.id)
                || row.projectId !== projectRaw.id || typeof row.filename !== "string" || !row.filename
                || typeof row.mimeType !== "string" || !/^[a-zA-Z0-9!#$&^_.+-]+\/[a-zA-Z0-9!#$&^_.+-]+(?:;[a-zA-Z0-9=._ ,"+-]+)*$/.test(row.mimeType)) {
                throw new PackageError("媒体元数据无效、重复或不属于当前项目");
            }
            if (row.libraryRetained !== undefined && typeof row.libraryRetained !== "boolean") throw new PackageError("素材保留标记无效");
            mediaMetadata.set(row.id, {
                filename: row.filename,
                mimeType: row.mimeType,
                libraryRetained: row.libraryRetained
            });
        }
    }
    const projectId = createId("prj");
    const at = nowIso();
    const mediaMap = new Map<string, string>();
    const mediaRecords: MediaRecord[] = [];
    const mediaFiles = zip.file(/^media\//);
    for (const entry of mediaFiles) {
        if (entry.dir) continue;
        const base = entry.name.split("/").pop() ?? entry.name;
        const oldId = base.replace(/\.[^.]+$/, "");
        if (mediaMap.has(oldId)) throw new PackageError("项目包中存在重复媒体 ID");
        const metadata = mediaMetadata.get(oldId);
        if (mediaMetadataRaw !== undefined && !metadata) throw new PackageError("媒体缺少元数据");
        const newId = remapId(mediaMap, oldId, "med")!;
        const blob = await entry.async("blob");
        const mimeType = metadata?.mimeType ?? (blob.type || mimeForFilename(base));
        mediaRecords.push({
            id: newId,
            projectId,
            mimeType,
            filename: metadata?.filename ?? base,
            libraryRetained: metadata?.libraryRetained,
            blob: new Blob([blob], {type: mimeType}),
        });
    }

    if ([...mediaMetadata.keys()].some((id) => !mediaMap.has(id))) throw new PackageError("媒体元数据对应的文件缺失");

    const {
        references,
        chunks: referenceChunks
    } = await remapReferencePackage(referencePackage, projectId, mediaMap, mediaRecords);

    const {
        project,
        characters,
        scenes,
        props,
        styles,
        episodes,
        shots,
        memories,
        memoryVersions,
        remappedAudioPackage
    } =
        remapProjectPackageRows(parsed, {projectId, at, mediaMap});

    try {
        await db.transaction(
            "rw",
            [
                ...AUDIO_TABLES,
                db.projects,
                db.characters,
                db.scenes,
                db.props,
                db.styles,
                db.episodes,
                db.shots,
                db.media,
                db.projectMemories,
                db.projectMemoryVersions,
                db.projectReferences,
                db.referenceChunks,
            ],
            async (db) => {
                await db.projects.add(project);
                if (characters.length) await db.characters.bulkAdd(characters);
                if (scenes.length) await db.scenes.bulkAdd(scenes);
                if (props.length) await db.props.bulkAdd(props);
                if (styles.length) await db.styles.bulkAdd(styles);
                if (episodes.length) await db.episodes.bulkAdd(episodes);
                if (shots.length) await db.shots.bulkAdd(shots);
                if (mediaRecords.length) await db.media.bulkAdd(mediaRecords);
                await insertAudioPackage(remappedAudioPackage, db);
                if (references.length) await db.projectReferences.bulkAdd(references);
                if (referenceChunks.length) await db.referenceChunks.bulkAdd(referenceChunks);
                if (memories.length) await db.projectMemories.bulkAdd(memories);
                if (memoryVersions.length)
                    await db.projectMemoryVersions.bulkAdd(memoryVersions);
            },
        );
    } catch (error) {
        if (error instanceof StorageError && error.certainty === "unknown") throw error;
        throw new PackageError(
            error instanceof Error ? `导入失败：${error.message}` : "导入失败",
        );
    }

    return project;
}

import {db} from "@/db/database";
import {generationImageDimensions} from "@/lib/agent/generationMedia";
import {
    type ParsedReference,
    type ProjectReference,
    REFERENCE_LIMITS as LIMITS,
    type ReferenceKind
} from "@/domain/references";
import {isStudioLibrary} from "@/domain/types";
import {createId, nowIso} from "@/lib/ids";
import {assertReferenceSignature, identifyReference, parseTextReference} from "./parse";
import {binaryByteLength} from "@/domain/binary";
import {readBinaryBlob, verifyBinaryAvailable} from "@/lib/storage/binary";

export interface ReferenceImportOptions {
    signal?: AbortSignal;
    onProgress?: (reference: ProjectReference) => void
}

async function parseDocxInWorker(buffer: ArrayBuffer, signal?: AbortSignal): Promise<ParsedReference> {
    const worker = new Worker(new URL("./docx.worker.ts", import.meta.url), {type: "module"});
    return new Promise((resolve, reject) => {
        const finish = (error?: unknown, result?: ParsedReference) => {
            clearTimeout(timer);
            signal?.removeEventListener("abort", abort);
            worker.terminate();
            if (error) reject(error); else resolve(result!);
        };
        const abort = () => finish(signal?.reason ?? new Error("解析已取消"));
        const timer = setTimeout(() => finish(new Error("DOCX 解析超时，请拆分文档后重试")), LIMITS.workerTimeoutMs);
        worker.onmessage = (event: MessageEvent<{
            result?: ParsedReference;
            error?: string
        }>) => finish(event.data.error ? new Error(event.data.error) : undefined, event.data.result);
        worker.onerror = () => finish(new Error("DOCX 解析失败，请检查文件后重试"));
        signal?.addEventListener("abort", abort, {once: true});
        if (signal?.aborted) abort(); else worker.postMessage(buffer, [buffer]);
    });
}

export async function parseReferenceFile(buffer: ArrayBuffer, kind: ReferenceKind, mimeType: string, signal?: AbortSignal): Promise<ParsedReference> {
    signal?.throwIfAborted();
    if (kind === "text") return parseTextReference(buffer);
    if (kind === "pdf") return (await import("./pdf")).parsePdfReference(buffer, signal);
    if (kind === "docx") return parseDocxInWorker(buffer, signal);
    const dimensions = await generationImageDimensions(new Blob([buffer], {type: mimeType}));
    if (dimensions.width * dimensions.height > 100_000_000) throw new Error("图片像素超过 1 亿，请缩小后重试");
    if (typeof createImageBitmap !== "undefined") {
        const image = await createImageBitmap(new Blob([buffer], {type: mimeType})).catch(() => {
            throw new Error("图片已损坏，无法解码");
        });
        try {
            if (image.width * image.height > 100_000_000) throw new Error("图片像素超过 1 亿，请缩小后重试");
        } finally {
            image.close();
        }
    }
    return {
        chunks: [],
        coverage: {totalUnits: 1, processedUnits: 1, emptyUnits: [], characters: 0, truncated: false},
        warnings: []
    };
}

async function finishImport(reference: ProjectReference, buffer: ArrayBuffer, options: ReferenceImportOptions): Promise<ProjectReference> {
    options.onProgress?.(reference);
    let parsed: ParsedReference | undefined;
    let error: string | undefined;
    try {
        parsed = await parseReferenceFile(buffer, reference.kind, reference.mimeType, options.signal);
        options.signal?.throwIfAborted();
    } catch (failure) {
        error = options.signal?.aborted ? "解析已取消，可以重试" : failure instanceof Error ? failure.message : "解析失败，请重试";
    }
    return db.transaction("rw", [db.projects, db.projectReferences, db.referenceChunks], async (db) => {
        const current = await db.projectReferences.get(reference.id);
        if (!current || current.operationId !== reference.operationId || current.status !== "parsing" || !(await db.projects.get(reference.projectId))) throw new Error("资料已移除或本次解析已被替代");
        const next: ProjectReference = {
            ...current,
            updatedAt: nowIso(),
            status: error ? "failed" : parsed!.coverage.truncated || parsed!.coverage.emptyUnits.length > 0 && reference.kind === "pdf" ? "partial" : "ready",
            error,
            coverage: parsed?.coverage ?? current.coverage,
            warnings: parsed?.warnings ?? [],
        };
        await db.referenceChunks.where("referenceId").equals(reference.id).delete();
        if (parsed?.chunks.length) await db.referenceChunks.bulkAdd(parsed.chunks.map((chunk) => ({
            ...chunk,
            id: createId("rfc"),
            referenceId: reference.id,
            revision: reference.revision,
            projectId: reference.projectId
        })));
        await db.projectReferences.put(next);
        return next;
    });
}

async function importSource(projectId: string, file: File, options: ReferenceImportOptions, existingMediaId?: string): Promise<ProjectReference> {
    const format = identifyReference(file);
    if (isStudioLibrary(projectId) || !(await db.projects.get(projectId))) throw new Error("请先选择一个项目，再添加参考资料");
    options.signal?.throwIfAborted();
    const buffer = await file.arrayBuffer();
    assertReferenceSignature(new Uint8Array(buffer), format.kind, format.mimeType);
    const digest = [...new Uint8Array(await crypto.subtle.digest("SHA-256", buffer))].map((byte) => byte.toString(16).padStart(2, "0")).join("");
    options.signal?.throwIfAborted();
    const operationId = createId("parse");
    const reference = await db.transaction("rw", [db.projects, db.media, db.projectReferences], async (db) => {
        options.signal?.throwIfAborted();
        if (!(await db.projects.get(projectId))) throw new Error("项目已删除");
        const duplicate = await db.projectReferences.where("[projectId+digest]").equals([projectId, digest]).filter((row) => row.status !== "unavailable").first();
        if (duplicate) return duplicate;
        const mediaId = existingMediaId ?? createId("med");
        if (existingMediaId) {
            const media = await db.media.get(existingMediaId);
            if (!media || media.projectId !== projectId || binaryByteLength(media.blob) !== file.size) throw new Error("图片已不可用");
            await db.waitFor(verifyBinaryAvailable(media.blob, options.signal));
        } else await db.media.add({
            id: mediaId,
            projectId,
            filename: file.name,
            mimeType: format.mimeType,
            blob: new Blob([buffer], {type: format.mimeType})
        });
        const at = nowIso();
        const row: ProjectReference = {
            ...format,
            id: createId("ref"),
            projectId,
            mediaId,
            digest,
            filename: file.name,
            size: file.size,
            revision: 1,
            operationId,
            status: "parsing",
            coverage: {totalUnits: 0, processedUnits: 0, emptyUnits: [], characters: 0, truncated: false},
            warnings: [],
            createdAt: at,
            updatedAt: at
        };
        await db.projectReferences.add(row);
        await db.projects.update(projectId, {updatedAt: at});
        return row;
    });
    if (reference.operationId !== operationId) return reference;
    return finishImport(reference, buffer, options);
}

export function importReferenceFile(projectId: string, file: File, options: ReferenceImportOptions = {}): Promise<ProjectReference> {
    return importSource(projectId, file, options);
}

/** Import/reuse generated or business-owned pixels without duplicating its Blob. */
export async function registerProjectImage(projectId: string, mediaId: string, options: ReferenceImportOptions = {}): Promise<ProjectReference> {
    const media = await db.media.get(mediaId);
    if (!media || media.projectId !== projectId) throw new Error("图片不属于当前项目或已删除");
    const extensions: Record<string, string> = {"image/png": "png", "image/jpeg": "jpg", "image/webp": "webp"};
    const ext = extensions[media.mimeType];
    if (!ext) throw new Error("当前仅支持 PNG、JPEG 和 WebP 图片");
    const filename = /\.(png|jpe?g|webp)$/i.test(media.filename) ? media.filename : `${media.filename}.${ext}`;
    return importSource(projectId, new File([await readBinaryBlob(media.blob, options.signal)], filename, {type: media.mimeType}), options, mediaId);
}

/** Explicitly recover an interrupted local parse; no network or model request. */
export async function retryReferenceImport(projectId: string, referenceId: string, options: ReferenceImportOptions = {}): Promise<ProjectReference> {
    const source = await db.transaction("r", [db.projects, db.projectReferences, db.media], async (db) => {
        const row = await db.projectReferences.get(referenceId);
        if (isStudioLibrary(projectId) || !(await db.projects.get(projectId)) || !row || row.projectId !== projectId || row.status === "unavailable") throw new Error("资料已不可用");
        const media = await db.media.get(row.mediaId);
        if (!media || media.projectId !== projectId) throw new Error("原始文件已不可用");
        return {row, media};
    });
    if (source.row.status === "ready" || source.row.status === "partial") return source.row;
    const buffer = await (await readBinaryBlob(source.media.blob, options.signal)).arrayBuffer();
    options.signal?.throwIfAborted();
    const reference = await db.transaction("rw", [db.projects, db.projectReferences], async (db) => {
        const row = await db.projectReferences.get(referenceId);
        if (!row || row.status === "unavailable" || row.operationId !== source.row.operationId || !(await db.projects.get(projectId))) throw new Error("资料状态已变化，请刷新后重试");
        const next: ProjectReference = {
            ...row,
            status: "parsing",
            error: undefined,
            operationId: createId("parse"),
            updatedAt: nowIso()
        };
        await db.projectReferences.put(next);
        return next;
    });
    return finishImport(reference, buffer, options);
}

import {z} from "zod";
import type {ProjectReference, ReferenceChunk} from "@/domain/references";
import {REFERENCE_LIMITS as LIMITS} from "@/domain/references";
import type {MediaRecord} from "@/domain/types";
import {createId} from "@/lib/ids";
import {assertReferenceSignature, identifyReference} from "./parse";
import {binaryByteLength} from "@/domain/binary";
import {withBinaryReadLease} from "@/lib/storage/binary";

const integer = z.number().int().nonnegative();
const coverage = z.object({
    totalUnits: integer,
    processedUnits: integer,
    emptyUnits: z.array(z.number().int().positive()).max(LIMITS.pages),
    characters: integer.max(LIMITS.characters),
    truncated: z.boolean()
});
const referenceSchema = z.object({
    id: z.string().min(1),
    projectId: z.string().min(1),
    mediaId: z.string().min(1),
    digest: z.string().regex(/^[a-f0-9]{64}$/),
    filename: z.string().min(1).max(1000),
    mimeType: z.string(),
    kind: z.enum(["image", "text", "pdf", "docx"]),
    size: integer.max(LIMITS.documentBytes),
    revision: z.number().int().positive(),
    operationId: z.string(),
    status: z.enum(["parsing", "ready", "partial", "failed", "unavailable"]),
    coverage,
    warnings: z.array(z.string().max(4000)).max(100),
    error: z.string().max(4000).optional(),
    createdAt: z.string(),
    updatedAt: z.string(),
});
const chunkSchema = z.object({
    id: z.string().min(1),
    projectId: z.string().min(1),
    referenceId: z.string().min(1),
    revision: z.number().int().positive(),
    index: integer,
    text: z.string().max(LIMITS.chunkCharacters),
    locator: z.object({
        kind: z.enum(["page", "lines", "paragraph"]),
        start: z.number().int().positive(),
        end: z.number().int().positive()
    }),
});

export function parseReferencePackage(rawRows: unknown, rawChunks: unknown, projectId: unknown) {
    const references = z.array(referenceSchema).parse(rawRows ?? []);
    const chunks = z.array(chunkSchema).parse(rawChunks ?? []);
    const byId = new Map(references.map((row) => [row.id, row]));
    const fail = () => {
        throw new Error("参考资料归属、正文或版本不一致");
    };
    if (byId.size !== references.length || new Set(chunks.map((chunk) => chunk.id)).size !== chunks.length) fail();
    for (const row of references) {
        if (row.projectId !== projectId || projectId === "studio" || row.coverage.processedUnits > row.coverage.totalUnits) fail();
        if (row.coverage.emptyUnits.some((unit) => unit > row.coverage.totalUnits)) fail();
        const parts = chunks.filter((part) => part.referenceId === row.id).sort((a, b) => a.index - b.index);
        if (parts.some((part, i) => part.index !== i || part.revision !== row.revision || part.projectId !== projectId || part.locator.end < part.locator.start || part.locator.end > row.coverage.totalUnits || part.locator.kind !== (row.kind === "pdf" ? "page" : row.kind === "docx" ? "paragraph" : "lines"))) fail();
        const textCharacters = parts.reduce((sum, part) => sum + part.text.length, 0);
        if (textCharacters > LIMITS.characters) fail();
        if (row.status === "ready" || row.status === "partial") {
            if (textCharacters !== row.coverage.characters) fail();
            if (!row.coverage.truncated && row.coverage.processedUnits !== row.coverage.totalUnits) fail();
            const incomplete = row.coverage.truncated || row.kind === "pdf" && row.coverage.emptyUnits.length > 0;
            if ((row.status === "partial") !== incomplete) fail();
        }
        if (new Set(row.coverage.emptyUnits).size !== row.coverage.emptyUnits.length || row.kind !== "pdf" && row.coverage.emptyUnits.length > 0) fail();
        if ((row.status === "unavailable" || row.status === "failed" || row.status === "parsing" || row.kind === "image") && parts.length) fail();
    }
    if (chunks.some((part) => !byId.has(part.referenceId))) fail();
    return {references, chunks};
}

/** All blob verification happens before opening the import transaction. */
export async function remapReferencePackage(input: ReturnType<typeof parseReferencePackage>, projectId: string, mediaMap: Map<string, string>, media: MediaRecord[]) {
    const ids = new Map(input.references.map((row) => [row.id, createId("ref")]));
    const references: ProjectReference[] = [];
    for (const row of input.references) {
        const mediaId = mediaMap.get(row.mediaId);
        if (row.status !== "unavailable") {
            const record = media.find((entry) => entry.id === mediaId);
            if (!record || binaryByteLength(record.blob) !== row.size) throw new Error("参考资料缺少原始文件或大小不符");
            const format = identifyReference({name: row.filename, size: row.size});
            if (format.kind !== row.kind || format.mimeType !== row.mimeType) throw new Error("参考资料文件类型不一致");
            const bytes = await withBinaryReadLease(record.blob, async lease => (await lease.readBlob()).arrayBuffer());
            assertReferenceSignature(new Uint8Array(bytes), row.kind, row.mimeType);
            const digest = [...new Uint8Array(await crypto.subtle.digest("SHA-256", bytes))].map((byte) => byte.toString(16).padStart(2, "0")).join("");
            if (digest !== row.digest) throw new Error("参考资料原始文件校验失败");
            record.filename = row.filename;
            record.mimeType = row.mimeType;
            record.blob = new Blob([bytes], {type: row.mimeType});
        }
        references.push({
            ...row,
            id: ids.get(row.id)!,
            projectId,
            mediaId: mediaId ?? createId("unavailable"),
            operationId: createId("import"),
            ...(row.status === "parsing" ? {status: "failed", error: "导入前解析尚未完成，请重试解析"} : {})
        });
    }
    const chunks: ReferenceChunk[] = input.chunks.map((part) => ({
        ...part,
        id: createId("rfc"),
        projectId,
        referenceId: ids.get(part.referenceId)!
    }));
    return {references, chunks};
}
